import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { BuildResults, CoverageReport, Tests, TestSummary } from "../src/types.ts";

const dir = join(import.meta.dirname, "..", "fixtures", "json");
const load = <T>(name: string): T => JSON.parse(readFileSync(join(dir, name), "utf8")) as T;

/** fixtures/json is generated by scripts/generate-fixtures.sh; the repository root is "/WORKSPACE". */
export const WORKSPACE = "/WORKSPACE";

export const fixtures = {
  summary: load<TestSummary>("summary.json"),
  tests: load<Tests>("tests.json"),
  build: load<BuildResults>("build-results.json"),
  coverage: load<CoverageReport>("coverage.json"),
};
